#!/usr/bin/env python3
"""Write docs/samples.md: per analysis, every input file, its normalisation
and the plot group it is merged into (generated from config/samples/*.yaml)."""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from benchlib import REPO, load_config  # noqa: E402


def main():
    out = ["# Samples and merge groups", "",
           "Generated by `scripts/list_samples.py` from `config/samples/*.yaml`.",
           "MC normalisation per sample: histograms x 1/(sumw x eff); XSection and Lumi",
           "(10064 pb^-1) are applied per event in the ADL. Data: no scaling.", ""]
    for path in sorted((REPO / "config" / "samples").glob("*.yaml")):
        cfg = load_config(path)
        group_of = {k: g for g, keys in cfg["groups"].items() for k in keys}
        out += [f"## {cfg['analysis']}", "",
                f"Normalisation table: {cfg['normalisation']['source']}", "",
                "| group | sample | DSID | file | xsec [pb] | sumw | eff |",
                "|---|---|---|---|---|---|---|"]
        for key, s in sorted(cfg["samples"].items(), key=lambda kv: (group_of[kv[0]], kv[0])):
            mc = s["type"] == "mc"
            out.append(f"| {group_of[key]} | {key} | {s.get('dsid', '')} | `{s['file']}` | "
                       f"{s['xsec'] if mc else ''} | {s['sumw'] if mc else ''} | {s['eff'] if mc else ''} |")
        out.append("")
    dest = REPO / "docs" / "samples.md"
    dest.write_text("\n".join(out))
    print(f"wrote {dest.relative_to(REPO)}")


if __name__ == "__main__":
    main()
